<?php require '../config/database.php'; require_once '../config/auth.php'; require_role('admin'); $rows=mysqli_query($conn,"SELECT h.*,u.full_name FROM health_records h JOIN members m ON h.member_id=m.id JOIN users u ON m.user_id=u.id ORDER BY h.record_date DESC"); ?>
<!DOCTYPE html><html><head><title>Health Records</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="layout"><?php include '_nav.php'; ?><main class="main"><h1>Medical & Fitness Records</h1><table class="table"><tr><th>Member</th><th>Date</th><th>BP</th><th>Heart</th><th>Sugar</th><th>Temp</th><th>BMI</th><th>Status</th></tr><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=e($r['full_name'])?></td><td><?=$r['record_date']?></td><td><?=$r['systolic']?>/<?=$r['diastolic']?></td><td><?=$r['heart_rate']?></td><td><?=$r['blood_sugar']?></td><td><?=$r['temperature']?></td><td><?=$r['bmi']?></td><td><span class="badge"><?=e($r['status'])?></span></td></tr><?php endwhile;?></table></main></div></body></html>
